import java.util.*; class Solution { public int minCut(String s) { int n = s.length(); if (n <= 1) return 0; boolean[][] isPal = new boolean[n][n]; for (int len = 1; len <= n; len++) { for (int i = 0; i <= n - len; i++) { int j = i + len - 1; if (s.charAt(i) == s.charAt(j)) { isPal[i][j] = (len <= 2) || isPal[i + 1][j - 1]; } } } int[] dp = new int[n]; for (int i = 0; i < n; i++) { if (isPal[0][i]) { dp[i] = 0; } else { dp[i] = i; for (int j = 0; j < i; j++) { if (isPal[j + 1][i]) { dp[i] = Math.min(dp[i], dp[j] + 1); } } } } return dp[n - 1]; } }